#!/usr/bin/env bash
set -Eeuo pipefail

database_password_variables=(
  CONTROL_DB_PASSWORD CONTROL_MIGRATION_DB_PASSWORD
  COMPILER_DB_PASSWORD COMPILER_MIGRATION_DB_PASSWORD
  AUDIENCE_DB_PASSWORD AUDIENCE_MIGRATION_DB_PASSWORD
  DECISION_DB_PASSWORD DECISION_MIGRATION_DB_PASSWORD
  BENEFIT_DB_PASSWORD BENEFIT_MIGRATION_DB_PASSWORD
  EVENTS_DB_PASSWORD EVENTS_MIGRATION_DB_PASSWORD
  JOURNEY_DB_PASSWORD JOURNEY_MIGRATION_DB_PASSWORD
  ENGAGEMENT_DB_PASSWORD ENGAGEMENT_MIGRATION_DB_PASSWORD
  MEASUREMENT_DB_PASSWORD MEASUREMENT_MIGRATION_DB_PASSWORD
)
for variable_name in "${database_password_variables[@]}"; do
  value="${!variable_name:?${variable_name} is required}"
  case "${value}" in
    *[!A-Za-z0-9_-]*) echo "${variable_name} must contain only letters, numbers, _ or -" >&2; exit 1 ;;
  esac
done
case "${KEYCLOAK_DB_PASSWORD:?KEYCLOAK_DB_PASSWORD is required}" in
  *[!A-Za-z0-9_-]*) echo "KEYCLOAK_DB_PASSWORD must contain only letters, numbers, _ or -" >&2; exit 1 ;;
esac

mysql --protocol=socket -uroot -p"${MYSQL_ROOT_PASSWORD}" <<SQL
CREATE DATABASE IF NOT EXISTS marketing_control CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
CREATE DATABASE IF NOT EXISTS marketing_compiler CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
CREATE DATABASE IF NOT EXISTS marketing_decision CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
CREATE DATABASE IF NOT EXISTS marketing_audience CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
CREATE DATABASE IF NOT EXISTS marketing_benefit CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
CREATE DATABASE IF NOT EXISTS marketing_events CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
CREATE DATABASE IF NOT EXISTS marketing_journey CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
CREATE DATABASE IF NOT EXISTS marketing_engagement CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
CREATE DATABASE IF NOT EXISTS marketing_measurement CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
CREATE DATABASE IF NOT EXISTS marketing_keycloak CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;

CREATE USER IF NOT EXISTS 'control_app'@'%' IDENTIFIED BY '${CONTROL_DB_PASSWORD}';
CREATE USER IF NOT EXISTS 'control_migrator'@'%' IDENTIFIED BY '${CONTROL_MIGRATION_DB_PASSWORD}';
ALTER USER 'control_app'@'%' IDENTIFIED BY '${CONTROL_DB_PASSWORD}';
ALTER USER 'control_migrator'@'%' IDENTIFIED BY '${CONTROL_MIGRATION_DB_PASSWORD}';
GRANT SELECT, INSERT, UPDATE, DELETE ON marketing_control.* TO 'control_app'@'%';
GRANT SELECT, INSERT, UPDATE, DELETE, CREATE, ALTER, DROP, INDEX, REFERENCES ON marketing_control.* TO 'control_migrator'@'%';

CREATE USER IF NOT EXISTS 'compiler_app'@'%' IDENTIFIED BY '${COMPILER_DB_PASSWORD}';
CREATE USER IF NOT EXISTS 'compiler_migrator'@'%' IDENTIFIED BY '${COMPILER_MIGRATION_DB_PASSWORD}';
ALTER USER 'compiler_app'@'%' IDENTIFIED BY '${COMPILER_DB_PASSWORD}';
ALTER USER 'compiler_migrator'@'%' IDENTIFIED BY '${COMPILER_MIGRATION_DB_PASSWORD}';
GRANT SELECT, INSERT, UPDATE, DELETE ON marketing_compiler.* TO 'compiler_app'@'%';
GRANT SELECT, INSERT, UPDATE, DELETE, CREATE, ALTER, DROP, INDEX, REFERENCES ON marketing_compiler.* TO 'compiler_migrator'@'%';

CREATE USER IF NOT EXISTS 'audience_app'@'%' IDENTIFIED BY '${AUDIENCE_DB_PASSWORD}';
CREATE USER IF NOT EXISTS 'audience_migrator'@'%' IDENTIFIED BY '${AUDIENCE_MIGRATION_DB_PASSWORD}';
ALTER USER 'audience_app'@'%' IDENTIFIED BY '${AUDIENCE_DB_PASSWORD}';
ALTER USER 'audience_migrator'@'%' IDENTIFIED BY '${AUDIENCE_MIGRATION_DB_PASSWORD}';
GRANT SELECT, INSERT, UPDATE, DELETE ON marketing_audience.* TO 'audience_app'@'%';
GRANT SELECT, INSERT, UPDATE, DELETE, CREATE, ALTER, DROP, INDEX, REFERENCES ON marketing_audience.* TO 'audience_migrator'@'%';

CREATE USER IF NOT EXISTS 'decision_app'@'%' IDENTIFIED BY '${DECISION_DB_PASSWORD}';
CREATE USER IF NOT EXISTS 'decision_migrator'@'%' IDENTIFIED BY '${DECISION_MIGRATION_DB_PASSWORD}';
ALTER USER 'decision_app'@'%' IDENTIFIED BY '${DECISION_DB_PASSWORD}';
ALTER USER 'decision_migrator'@'%' IDENTIFIED BY '${DECISION_MIGRATION_DB_PASSWORD}';
GRANT SELECT, INSERT, UPDATE, DELETE ON marketing_decision.* TO 'decision_app'@'%';
GRANT SELECT, INSERT, UPDATE, DELETE, CREATE, ALTER, DROP, INDEX, REFERENCES ON marketing_decision.* TO 'decision_migrator'@'%';

CREATE USER IF NOT EXISTS 'benefit_app'@'%' IDENTIFIED BY '${BENEFIT_DB_PASSWORD}';
CREATE USER IF NOT EXISTS 'benefit_migrator'@'%' IDENTIFIED BY '${BENEFIT_MIGRATION_DB_PASSWORD}';
ALTER USER 'benefit_app'@'%' IDENTIFIED BY '${BENEFIT_DB_PASSWORD}';
ALTER USER 'benefit_migrator'@'%' IDENTIFIED BY '${BENEFIT_MIGRATION_DB_PASSWORD}';
GRANT SELECT, INSERT, UPDATE, DELETE ON marketing_benefit.* TO 'benefit_app'@'%';
GRANT SELECT, INSERT, UPDATE, DELETE, CREATE, ALTER, DROP, INDEX, REFERENCES ON marketing_benefit.* TO 'benefit_migrator'@'%';

CREATE USER IF NOT EXISTS 'events_app'@'%' IDENTIFIED BY '${EVENTS_DB_PASSWORD}';
CREATE USER IF NOT EXISTS 'events_migrator'@'%' IDENTIFIED BY '${EVENTS_MIGRATION_DB_PASSWORD}';
ALTER USER 'events_app'@'%' IDENTIFIED BY '${EVENTS_DB_PASSWORD}';
ALTER USER 'events_migrator'@'%' IDENTIFIED BY '${EVENTS_MIGRATION_DB_PASSWORD}';
GRANT SELECT, INSERT, UPDATE, DELETE ON marketing_events.* TO 'events_app'@'%';
GRANT SELECT, INSERT, UPDATE, DELETE, CREATE, ALTER, DROP, INDEX, REFERENCES ON marketing_events.* TO 'events_migrator'@'%';

CREATE USER IF NOT EXISTS 'journey_app'@'%' IDENTIFIED BY '${JOURNEY_DB_PASSWORD}';
CREATE USER IF NOT EXISTS 'journey_migrator'@'%' IDENTIFIED BY '${JOURNEY_MIGRATION_DB_PASSWORD}';
ALTER USER 'journey_app'@'%' IDENTIFIED BY '${JOURNEY_DB_PASSWORD}';
ALTER USER 'journey_migrator'@'%' IDENTIFIED BY '${JOURNEY_MIGRATION_DB_PASSWORD}';
GRANT SELECT, INSERT, UPDATE, DELETE ON marketing_journey.* TO 'journey_app'@'%';
GRANT SELECT, INSERT, UPDATE, DELETE, CREATE, ALTER, DROP, INDEX, REFERENCES ON marketing_journey.* TO 'journey_migrator'@'%';

CREATE USER IF NOT EXISTS 'engagement_app'@'%' IDENTIFIED BY '${ENGAGEMENT_DB_PASSWORD}';
CREATE USER IF NOT EXISTS 'engagement_migrator'@'%' IDENTIFIED BY '${ENGAGEMENT_MIGRATION_DB_PASSWORD}';
ALTER USER 'engagement_app'@'%' IDENTIFIED BY '${ENGAGEMENT_DB_PASSWORD}';
ALTER USER 'engagement_migrator'@'%' IDENTIFIED BY '${ENGAGEMENT_MIGRATION_DB_PASSWORD}';
GRANT SELECT, INSERT, UPDATE, DELETE ON marketing_engagement.* TO 'engagement_app'@'%';
GRANT SELECT, INSERT, UPDATE, DELETE, CREATE, ALTER, DROP, INDEX, REFERENCES ON marketing_engagement.* TO 'engagement_migrator'@'%';

CREATE USER IF NOT EXISTS 'measurement_app'@'%' IDENTIFIED BY '${MEASUREMENT_DB_PASSWORD}';
CREATE USER IF NOT EXISTS 'measurement_migrator'@'%' IDENTIFIED BY '${MEASUREMENT_MIGRATION_DB_PASSWORD}';
ALTER USER 'measurement_app'@'%' IDENTIFIED BY '${MEASUREMENT_DB_PASSWORD}';
ALTER USER 'measurement_migrator'@'%' IDENTIFIED BY '${MEASUREMENT_MIGRATION_DB_PASSWORD}';
GRANT SELECT, INSERT, UPDATE, DELETE ON marketing_measurement.* TO 'measurement_app'@'%';
GRANT SELECT, INSERT, UPDATE, DELETE, CREATE, ALTER, DROP, INDEX, REFERENCES ON marketing_measurement.* TO 'measurement_migrator'@'%';

CREATE USER IF NOT EXISTS 'marketing_keycloak'@'%' IDENTIFIED BY '${KEYCLOAK_DB_PASSWORD}';
ALTER USER 'marketing_keycloak'@'%' IDENTIFIED BY '${KEYCLOAK_DB_PASSWORD}';
GRANT ALL PRIVILEGES ON marketing_keycloak.* TO 'marketing_keycloak'@'%';
FLUSH PRIVILEGES;
SQL
